// Extracted from SmtpEmailSender, so it speaks SMTP
public interface IEmailSender
{
    Task SendAsync(string to, string subject, string html, SmtpSettings smtp);
}

// One implementation, ever, but it got an interface too
public interface IPriceCalculator { decimal Total(Order order); }

public sealed class OrderService(
    IEmailSender email, IPriceCalculator prices, SmtpSettings smtp)
{
    public Task PlaceAsync(Order order)
    {
        // Business code builds HTML and picks SMTP settings
        var html = $"<p>Order {order.Id}: {prices.Total(order):C}</p>";
        return email.SendAsync(
            order.CustomerEmail, "Order placed", html, smtp);
    }
}

// Owned by the ordering code and named for what it needs
public interface IOrderNotifications
{
    Task OrderPlacedAsync(Order order, decimal total, CancellationToken ct);
}

public static class Pricing // pure policy: no interface needed
{
    public static decimal Total(Order o) => o.Lines.Sum(l => l.Price * l.Qty);
}

public sealed class PlaceOrder(IOrderNotifications notifications)
{
    public Task RunAsync(Order order, CancellationToken ct) =>
        notifications.OrderPlacedAsync(order, Pricing.Total(order), ct);
}

// The detail adapts itself to the policy's interface
public sealed class EmailOrderNotifications(SmtpSender smtp)
    : IOrderNotifications
{
    public Task OrderPlacedAsync(Order o, decimal total, CancellationToken ct) =>
        smtp.SendAsync(o.CustomerEmail, "Order placed", $"{total:C}", ct);
}
